import mongoose, { type Document, type Model, Schema } from "mongoose";

export type ApplicationStatus =
  | "pending"
  | "under_review"
  | "accepted"
  | "rejected";

export interface IApplication extends Document {
  student: mongoose.Types.ObjectId;
  university: mongoose.Types.ObjectId;
  status: ApplicationStatus;
  statement?: string;
  paymentStatus: "unpaid" | "paid";
  createdAt: Date;
  updatedAt: Date;
}

const applicationSchema = new Schema<IApplication>(
  {
    student: {
      type: Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },
    university: {
      type: Schema.Types.ObjectId,
      ref: "University",
      required: true,
    },
    status: {
      type: String,
      enum: ["pending", "under_review", "accepted", "rejected"],
      default: "pending",
    },
    statement: { type: String, trim: true },
    paymentStatus: {
      type: String,
      enum: ["unpaid", "paid"],
      default: "unpaid",
    },
  },
  { timestamps: true },
);

const Application: Model<IApplication> = mongoose.model<IApplication>(
  "Application",
  applicationSchema,
);
export default Application;

import mongoose, { type Document, type Model, Schema } from "mongoose";

export interface IPayment extends Document {
  student: mongoose.Types.ObjectId;
  application: mongoose.Types.ObjectId;
  stripePaymentIntentId: string;
  amount: number;
  currency: string;
  status: "created" | "succeeded" | "failed";
  createdAt: Date;
  updatedAt: Date;
}

const paymentSchema = new Schema<IPayment>(
  {
    student: {
      type: Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },
    application: {
      type: Schema.Types.ObjectId,
      ref: "Application",
      required: true,
    },
    stripePaymentIntentId: { type: String, required: true },
    amount: { type: Number, required: true },
    currency: { type: String, default: "usd" },
    status: {
      type: String,
      enum: ["created", "succeeded", "failed"],
      default: "created",
    },
  },
  { timestamps: true },
);

const Payment: Model<IPayment> = mongoose.model<IPayment>(
  "Payment",
  paymentSchema,
);
export default Payment;

import type { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";

export interface AuthRequest extends Request {
  userId?: string;
}

export function authenticate(
  req: AuthRequest,
  res: Response,
  next: NextFunction,
): void {
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ success: false, message: "No token provided" });
    return;
  }

  const token = authHeader.slice(7);
  const secret = process.env["JWT_SECRET"];
  if (!secret) {
    res.status(500).json({ success: false, message: "Server misconfiguration" });
    return;
  }

  try {
    const decoded = jwt.verify(token, secret) as { userId: string };
    req.userId = decoded.userId;
    next();
  } catch {
    res.status(401).json({ success: false, message: "Invalid or expired token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { validationResult } from "express-validator";

export function validate(req: Request, res: Response, next: NextFunction): void {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({ success: false, errors: errors.array() });
    return;
  }
  next();
}

import { Router } from "express";
import { body } from "express-validator";
import jwt from "jsonwebtoken";
import User from "../models/User.js";
import { authenticate, type AuthRequest } from "../middlewares/auth.js";
import { validate } from "../middlewares/validate.js";

const router = Router();

router.post(
  "/auth/register",
  [
    body("name").trim().notEmpty().withMessage("Name is required"),
    body("email").isEmail().withMessage("Valid email is required"),
    body("password")
      .isLength({ min: 6 })
      .withMessage("Password must be at least 6 characters"),
    body("phone").optional().isMobilePhone("any").withMessage("Invalid phone number"),
  ],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { name, email, password, phone } = req.body as {
        name: string;
        email: string;
        password: string;
        phone?: string;
      };

      const existing = await User.findOne({ email });
      if (existing) {
        return res
          .status(409)
          .json({ success: false, message: "Email already registered" });
      }

      const user = await User.create({ name, email, password, phone });

      const secret = process.env["JWT_SECRET"]!;
      const token = jwt.sign({ userId: user._id }, secret, { expiresIn: "7d" });

      return res.status(201).json({
        success: true,
        message: "Registration successful",
        token,
        user,
      });
    } catch (err) {
      req.log.error({ err }, "Register error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.post(
  "/auth/login",
  [
    body("email").isEmail().withMessage("Valid email is required"),
    body("password").notEmpty().withMessage("Password is required"),
  ],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { email, password } = req.body as { email: string; password: string };

      const user = await User.findOne({ email });
      if (!user) {
        return res
          .status(401)
          .json({ success: false, message: "Invalid credentials" });
      }

      const isMatch = await user.comparePassword(password);
      if (!isMatch) {
        return res
          .status(401)
          .json({ success: false, message: "Invalid credentials" });
      }

      const secret = process.env["JWT_SECRET"]!;
      const token = jwt.sign({ userId: user._id }, secret, { expiresIn: "7d" });

      return res.json({
        success: true,
        message: "Login successful",
        token,
        user,
      });
    } catch (err) {
      req.log.error({ err }, "Login error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.get("/auth/profile", authenticate, async (req: AuthRequest, res: any) => {
  try {
    const user = await User.findById(req.userId);
    if (!user) {
      return res.status(404).json({ success: false, message: "User not found" });
    }
    return res.json({ success: true, user });
  } catch (err) {
    req.log.error({ err }, "Profile error");
    return res.status(500).json({ success: false, message: "Server error" });
  }
});

export default router;

import { Router } from "express";
import { body, param } from "express-validator";
import University from "../models/University.js";
import { authenticate, type AuthRequest } from "../middlewares/auth.js";
import { validate } from "../middlewares/validate.js";

const router = Router();

const universityValidators = [
  body("name").trim().notEmpty().withMessage("University name is required"),
  body("country").trim().notEmpty().withMessage("Country is required"),
  body("course").trim().notEmpty().withMessage("Course is required"),
  body("applicationFee")
    .isFloat({ min: 0 })
    .withMessage("Application fee must be a non-negative number"),
  body("description").optional().trim(),
];

router.get("/universities", async (req: AuthRequest, res: any) => {
  try {
    const universities = await University.find().sort({ createdAt: -1 });
    return res.json({ success: true, count: universities.length, universities });
  } catch (err) {
    req.log.error({ err }, "Get universities error");
    return res.status(500).json({ success: false, message: "Server error" });
  }
});

router.post(
  "/universities",
  authenticate,
  universityValidators,
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { name, country, course, applicationFee, description } =
        req.body as {
          name: string;
          country: string;
          course: string;
          applicationFee: number;
          description?: string;
        };

      const university = await University.create({
        name,
        country,
        course,
        applicationFee,
        description,
      });

      return res.status(201).json({
        success: true,
        message: "University created",
        university,
      });
    } catch (err) {
      req.log.error({ err }, "Create university error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.put(
  "/universities/:id",
  authenticate,
  [param("id").isMongoId().withMessage("Invalid university ID"), ...universityValidators],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const university = await University.findByIdAndUpdate(
        req.params["id"],
        req.body,
        { new: true, runValidators: true },
      );

      if (!university) {
        return res
          .status(404)
          .json({ success: false, message: "University not found" });
      }

      return res.json({ success: true, message: "University updated", university });
    } catch (err) {
      req.log.error({ err }, "Update university error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.delete(
  "/universities/:id",
  authenticate,
  [param("id").isMongoId().withMessage("Invalid university ID")],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const university = await University.findByIdAndDelete(req.params["id"]);

      if (!university) {
        return res
          .status(404)
          .json({ success: false, message: "University not found" });
      }

      return res.json({ success: true, message: "University deleted" });
    } catch (err) {
      req.log.error({ err }, "Delete university error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

export default router;

import { Router } from "express";
import { body, param } from "express-validator";
import Application from "../models/Application.js";
import University from "../models/University.js";
import { authenticate, type AuthRequest } from "../middlewares/auth.js";
import { validate } from "../middlewares/validate.js";

const router = Router();

router.post(
  "/applications",
  authenticate,
  [
    body("universityId")
      .isMongoId()
      .withMessage("Valid university ID is required"),
    body("statement").optional().trim(),
  ],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { universityId, statement } = req.body as {
        universityId: string;
        statement?: string;
      };

      const university = await University.findById(universityId);
      if (!university) {
        return res
          .status(404)
          .json({ success: false, message: "University not found" });
      }

      const existing = await Application.findOne({
        student: req.userId,
        university: universityId,
      });
      if (existing) {
        return res.status(409).json({
          success: false,
          message: "You have already applied to this university",
        });
      }

      const application = await Application.create({
        student: req.userId,
        university: universityId,
        statement,
      });

      await application.populate(["student", "university"]);

      return res.status(201).json({
        success: true,
        message: "Application submitted",
        application,
      });
    } catch (err) {
      req.log.error({ err }, "Create application error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.get("/applications", authenticate, async (req: AuthRequest, res: any) => {
  try {
    const applications = await Application.find({ student: req.userId })
      .populate("university")
      .sort({ createdAt: -1 });

    return res.json({
      success: true,
      count: applications.length,
      applications,
    });
  } catch (err) {
    req.log.error({ err }, "Get applications error");
    return res.status(500).json({ success: false, message: "Server error" });
  }
});

router.get(
  "/applications/:id",
  authenticate,
  [param("id").isMongoId().withMessage("Invalid application ID")],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const application = await Application.findOne({
        _id: req.params["id"],
        student: req.userId,
      }).populate(["student", "university"]);

      if (!application) {
        return res
          .status(404)
          .json({ success: false, message: "Application not found" });
      }

      return res.json({ success: true, application });
    } catch (err) {
      req.log.error({ err }, "Get application error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

export default router;

import { Router } from "express";
import { body } from "express-validator";
import Stripe from "stripe";
import Application from "../models/Application.js";
import University from "../models/University.js";
import Payment from "../models/Payment.js";
import { authenticate, type AuthRequest } from "../middlewares/auth.js";
import { validate } from "../middlewares/validate.js";

const router = Router();

function getStripe(): Stripe {
  const key = process.env["STRIPE_SECRET_KEY"];
  if (!key) throw new Error("STRIPE_SECRET_KEY is not set");
  return new Stripe(key);
}

router.post(
  "/payments/create-order",
  authenticate,
  [
    body("applicationId")
      .isMongoId()
      .withMessage("Valid application ID is required"),
  ],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { applicationId } = req.body as { applicationId: string };

      const application = await Application.findOne({
        _id: applicationId,
        student: req.userId,
      }).populate<{ university: InstanceType<typeof University> }>("university");

      if (!application) {
        return res
          .status(404)
          .json({ success: false, message: "Application not found" });
      }

      if (application.paymentStatus === "paid") {
        return res
          .status(400)
          .json({ success: false, message: "Application fee already paid" });
      }

      const university = application.university as any;
      const amountInCents = Math.round(university.applicationFee * 100);

      const stripe = getStripe();
      const paymentIntent = await stripe.paymentIntents.create({
        amount: amountInCents,
        currency: "usd",
        metadata: {
          applicationId: applicationId,
          studentId: req.userId!,
          universityId: university._id.toString(),
        },
      });

      await Payment.create({
        student: req.userId,
        application: applicationId,
        stripePaymentIntentId: paymentIntent.id,
        amount: amountInCents,
        currency: "usd",
        status: "created",
      });

      return res.status(201).json({
        success: true,
        message: "Payment order created",
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
        amount: amountInCents,
        currency: "usd",
      });
    } catch (err) {
      req.log.error({ err }, "Create payment order error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.post(
  "/payments/verify",
  authenticate,
  [
    body("paymentIntentId")
      .notEmpty()
      .withMessage("paymentIntentId is required"),
  ],
  validate,
  async (req: AuthRequest, res: any) => {
    try {
      const { paymentIntentId } = req.body as { paymentIntentId: string };

      const stripe = getStripe();
      const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId);

      const payment = await Payment.findOne({
        stripePaymentIntentId: paymentIntentId,
        student: req.userId,
      });

      if (!payment) {
        return res
          .status(404)
          .json({ success: false, message: "Payment record not found" });
      }

      if (paymentIntent.status === "succeeded") {
        payment.status = "succeeded";
        await payment.save();

        await Application.findByIdAndUpdate(payment.application, {
          paymentStatus: "paid",
        });

        return res.json({
          success: true,
          message: "Payment verified successfully",
          payment,
        });
      }

      payment.status =
        paymentIntent.status === "canceled" ? "failed" : "created";
      await payment.save();

      return res.json({
        success: false,
        message: `Payment status: ${paymentIntent.status}`,
        payment,
      });
    } catch (err) {
      req.log.error({ err }, "Verify payment error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

router.get(
  "/payments/history",
  authenticate,
  async (req: AuthRequest, res: any) => {
    try {
      const payments = await Payment.find({ student: req.userId })
        .populate({
          path: "application",
          populate: { path: "university", select: "name country course applicationFee" },
        })
        .sort({ createdAt: -1 });

      return res.json({ success: true, count: payments.length, payments });
    } catch (err) {
      req.log.error({ err }, "Payment history error");
      return res.status(500).json({ success: false, message: "Server error" });
    }
  },
);

export default router;

import { Router, type IRouter } from "express";
import healthRouter from "./health.js";
import authRouter from "./auth.js";
import universitiesRouter from "./universities.js";
import applicationsRouter from "./applications.js";
import paymentsRouter from "./payments.js";

const router: IRouter = Router();

router.use(healthRouter);
router.use(authRouter);
router.use(universitiesRouter);
router.use(applicationsRouter);
router.use(paymentsRouter);

export default router;

import app from "./app.js";
import { logger } from "./lib/logger.js";
import { connectDB } from "./lib/db.js";

const rawPort = process.env["PORT"];

if (!rawPort) {
  throw new Error(
    "PORT environment variable is required but was not provided.",
  );
}

const port = Number(rawPort);

if (Number.isNaN(port) || port <= 0) {
  throw new Error(`Invalid PORT value: "${rawPort}"`);
}

async function start() {
  await connectDB();

  app.listen(port, (err?: Error) => {
    if (err) {
      logger.error({ err }, "Error listening on port");
      process.exit(1);
    }
    logger.info({ port }, "Server listening");
  });
}

start().catch((err) => {
  logger.error({ err }, "Failed to start server");
  process.exit(1);
});

import mongoose, { type Document, type Model, Schema } from "mongoose";
import bcrypt from "bcryptjs";

export interface IUser extends Document {
  name: string;
  email: string;
  password: string;
  phone?: string;
  createdAt: Date;
  updatedAt: Date;
  comparePassword(candidate: string): Promise<boolean>;
}

const userSchema = new Schema<IUser>(
  {
    name: { type: String, required: true, trim: true },
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true,
    },
    password: { type: String, required: true, minlength: 6 },
    phone: { type: String, trim: true },
  },
  { timestamps: true },
);

userSchema.pre("save", async function (next) {
  if (!this.isModified("password")) {
    next();
    return;
  }
  const salt = await bcrypt.genSalt(10);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

userSchema.methods["comparePassword"] = async function (
  candidate: string,
): Promise<boolean> {
  return bcrypt.compare(candidate, this.password as string);
};

userSchema.set("toJSON", {
  transform(_doc, ret: Record<string, unknown>) {
    ret["password"] = undefined;
    return ret;
  },
});

const User: Model<IUser> = mongoose.model<IUser>("User", userSchema);
export default User;

