import axios from "axios";

const TOKEN_KEY = "globetrek_token";

export const apiClient = axios.create({ baseURL: "/" });

apiClient.interceptors.request.use((config) => {
  const token = localStorage.getItem(TOKEN_KEY);
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

export const auth = {
  setToken: (token: string) => localStorage.setItem(TOKEN_KEY, token),
  getToken: () => localStorage.getItem(TOKEN_KEY),
  clearToken: () => localStorage.removeItem(TOKEN_KEY),
  isLoggedIn: () => !!localStorage.getItem(TOKEN_KEY),
};

export type User = {
  _id: string;
  name: string;
  email: string;
  phone?: string;
  createdAt: string;
};

export type University = {
  _id: string;
  name: string;
  country: string;
  course: string;
  applicationFee: number;
  description?: string;
  createdAt: string;
};

export type Application = {
  _id: string;
  student: User;
  university: University;
  status: "pending" | "under_review" | "accepted" | "rejected";
  statement?: string;
  paymentStatus: "unpaid" | "paid";
  createdAt: string;
};

export type Payment = {
  _id: string;
  stripePaymentIntentId: string;
  amount: number;
  currency: string;
  status: "created" | "succeeded" | "failed";
  application: Application;
  createdAt: string;
};

import { Link, useLocation } from "wouter";
import { auth } from "@/lib/api";
import { useCallback } from "react";
import { cn } from "@/lib/utils";

const navLinks = [
  { href: "/universities", label: "Universities" },
  { href: "/applications", label: "My Applications" },
  { href: "/payments", label: "Payments" },
  { href: "/profile", label: "Profile" },
];

export default function Layout({ children }: { children: React.ReactNode }) {
  const [location, navigate] = useLocation();

  const handleLogout = useCallback(() => {
    auth.clearToken();
    navigate("/login");
  }, [navigate]);

  const isLoggedIn = auth.isLoggedIn();

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <header className="sticky top-0 z-50 bg-[hsl(222,47%,11%)] text-white shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <Link href="/">
              <span className="flex items-center gap-2 cursor-pointer select-none">
                <span className="text-[hsl(43,100%,50%)] font-serif text-2xl font-bold tracking-tight">
                  Globe
                </span>
                <span className="font-serif text-2xl font-light tracking-tight">
                  Trek
                </span>
                <span className="ml-1 text-xs text-white/50 uppercase tracking-widest hidden sm:block self-end pb-1">
                  Overseas
                </span>
              </span>
            </Link>

            <nav className="hidden md:flex items-center gap-1">
              {isLoggedIn &&
                navLinks.map((link) => (
                  <Link key={link.href} href={link.href}>
                    <span
                      className={cn(
                        "px-4 py-2 rounded-md text-sm font-medium transition-colors cursor-pointer",
                        location === link.href
                          ? "bg-white/10 text-white"
                          : "text-white/70 hover:text-white hover:bg-white/5",
                      )}
                    >
                      {link.label}
                    </span>
                  </Link>
                ))}
            </nav>

            <div className="flex items-center gap-3">
              {isLoggedIn ? (
                <button
                  onClick={handleLogout}
                  className="text-sm text-white/70 hover:text-white transition-colors px-3 py-1.5 rounded border border-white/20 hover:border-white/40"
                >
                  Sign Out
                </button>
              ) : (
                <>
                  <Link href="/login">
